policies.statement:
permit(
  principal is AgentCore::OAuthUser,
  action,
  resource is AgentCore::Gateway
)
when {
  principal.hasTag("cognito:groups") &&
  principal.getTag("cognito:groups") like "*admin*"
};

forbid(
  principal,
  action,
  resource is AgentCore::Gateway
)
unless {
  principal is AgentCore::OAuthUser
};
